import json
def call(group,method,**kw):return execute_tool('editor_toolset.toolsets.'+group+'.'+method,json.dumps(kw)).get('returnValue')
def ref(s):return {'refPath':s}
def v(x,y,z):return {'x':x,'y':y,'z':z}
def props(obj,values):
    assert call('object.ObjectTools','set_properties',instance=obj,values=json.dumps(values))
def mesh(name,loc,size,mat='Steel',shape='Cube',yaw=0,pitch=0,movable=False,tag=None):
    a=call('scene.SceneTools','add_to_scene_from_asset',asset_path='/Engine/BasicShapes/'+shape,name=name,xform={'location':v(*loc),'scale':v(*[s/100 for s in size]),'rotation':{'pitch':pitch,'yaw':yaw,'roll':0}})
    c=call('actor.ActorTools','get_components',actor=a,component_type=ref('/Script/Engine.StaticMeshComponent'))[0]
    vals={'overrideMaterials':[ref('/Game/CompoundBreach/Materials/MI_'+mat+'.MI_'+mat)]}
    if movable:vals['mobility']='Movable'
    props(c,vals)
    if tag:props(a,{'tags':[tag]})
    return a
def sign(name,text,loc,yaw=0,size=45):
    a=call('scene.SceneTools','add_to_scene_from_class',actor_type=ref('/Script/Engine.TextRenderActor'),name=name,xform={'location':v(*loc),'rotation':{'pitch':0,'yaw':yaw,'roll':0}})
    c=call('actor.ActorTools','get_components',actor=a,component_type=ref('/Script/Engine.TextRenderComponent'))[0]
    props(c,{'text':text,'worldSize':size,'horizontalAlignment':'EHTA_Center','textRenderColor':{'r':0.85,'g':0.95,'b':1,'a':1}})
    return a
def run():
    changed=[]
    for a in call('scene.SceneTools','find_actors',name='InteriorLight',tag='',collision_channels=[]):
        old=json.loads(call('object.ObjectTools','get_properties',instance=a,properties=['tags']))['tags']
        props(a,{'tags':list(dict.fromkeys(old+['GeneratorRoomLight']))})
        c=call('actor.ActorTools','get_components',actor=a,component_type=ref('/Script/Engine.PointLightComponent'))[0]
        props(c,{'mobility':'Movable','intensity':750})
        changed.append(a)
    call("blueprint.BlueprintTools","write_graph_dsl",graph=ref("/Game/CompoundBreach/Blueprints/BP_EscapePlayer.BP_EscapePlayer:EventGraph"),code='(event EventBeginPlay\n  (Input|SetInputModeGameOnly :PlayerController (Game|GetPlayerController)))\n(event EventTick (DeltaSeconds)\n  (bind pc (Game|GetPlayerController))\n  (bind pos (Transformation|GetActorLocation))\n  (Variables|Default|SetPrompt "")\n  (if (Game|Player|WasInputKeyJustPressed :self pc :Key "R")\n    (Game|OpenLevel(byName) :LevelName "L_CompoundEscape"))\n  (if (not (Variables|Default|GetEscaped))\n    (bind (mx my) (Game|Player|GetInputMouseDelta :self pc))\n    (Pawn|Input|AddControllerYawInput :Val (* mx 0.65))\n    (Pawn|Input|AddControllerPitchInput :Val (* my -0.65))\n    (bind forward (Transformation|GetActorForwardVector))\n    (bind right (Transformation|GetActorRightVector))\n    (if (Game|Player|IsInputKeyDown :self pc :Key "W")\n      (Pawn|Input|AddMovementInput :WorldDirection forward :ScaleValue 1.0))\n    (if (Game|Player|IsInputKeyDown :self pc :Key "S")\n      (Pawn|Input|AddMovementInput :WorldDirection forward :ScaleValue -1.0))\n    (if (Game|Player|IsInputKeyDown :self pc :Key "D")\n      (Pawn|Input|AddMovementInput :WorldDirection right :ScaleValue 1.0))\n    (if (Game|Player|IsInputKeyDown :self pc :Key "A")\n      (Pawn|Input|AddMovementInput :WorldDirection right :ScaleValue -1.0))\n    (if (Game|Player|WasInputKeyJustPressed :self pc :Key "SpaceBar") (Character|Jump))\n    (if (not (Game|Player|IsInputKeyDown :self pc :Key "SpaceBar")) (Character|StopJumping))\n    (if (< (.z pos) -500.0)\n      (Transformation|SetActorLocation :NewLocation "(X=-600,Y=-2500,Z=540)" :bTeleport true))\n    (Variables|Default|SetObjective "Find the security keycard in A / PROCESSING")\n    (if (Variables|Default|GetHasKeycard)\n      (Variables|Default|SetObjective "Restore the generator in B / POWER"))\n    (if (and (Variables|Default|GetHasKeycard) (Variables|Default|GetPowerOnline))\n      (Variables|Default|SetObjective "Authorize the exit in C / CONTROL"))\n    (if (Variables|Default|GetGateUnlocked)\n      (Variables|Default|SetObjective "Gate released. Follow EXIT signs to the south gate."))\n    (bind use (Game|Player|WasInputKeyJustPressed :self pc :Key "E"))\n    (if (and (not (Variables|Default|GetHasKeycard)) (< (Math|Vector|VectorLength :A (- pos (Math|Vector|MakeVector -1800.0 -1200.0 100.0))) 240.0))\n      (Variables|Default|SetPrompt "[E] Collect SECURITY KEYCARD")\n      (if use\n        (Variables|Default|SetHasKeycard true)\n        (bind cards (Actor|GetAllActorswithTag :Tag "Keycard"))\n        (for card cards (Rendering|SetActorHiddenInGame :self card :bNewHidden true))))\n    (if (< (Math|Vector|VectorLength :A (- pos (Math|Vector|MakeVector 1800.0 -200.0 100.0))) 270.0)\n      (if (Variables|Default|GetPowerOnline)\n        (Variables|Default|SetPrompt "GENERATOR ONLINE")\n        (else\n          (Variables|Default|SetPrompt "[E] Start COMPOUND GENERATOR")\n          (if use\n            (Variables|Default|SetPowerOnline true)\n            (bind roomLights (Actor|GetAllActorswithTag :Tag "GeneratorRoomLight"))\n            (for roomLight roomLights\n              (bind pointLight (Utilities|Casting|CastToPointLight :Object roomLight)\n                (:then\n                  (Rendering|Components|Light|SetIntensity\n                    :self (Class|Light|GetLightComponent :self pointLight)\n                    :NewIntensity 5000.0))\n                (:CastFailed)))))))\n    (if (< (Math|Vector|VectorLength :A (- pos (Math|Vector|MakeVector -1800.0 1800.0 100.0))) 240.0)\n      (if (not (Variables|Default|GetPowerOnline))\n        (Variables|Default|SetPrompt "TERMINAL OFFLINE - restore power in B")\n        (elif (not (Variables|Default|GetHasKeycard))\n          (Variables|Default|SetPrompt "ACCESS DENIED - find keycard in A")\n          (else\n            (Variables|Default|SetPrompt "[E] Authorize EXIT GATE")\n            (if use (Variables|Default|SetGateUnlocked true))))))\n    (if (Variables|Default|GetGateUnlocked)\n      (if (< (Variables|Default|GetGateHeight) 700.0)\n        (Variables|Default|SetGateHeight (+ (Variables|Default|GetGateHeight) (* DeltaSeconds 180.0)))\n        (bind gates (Actor|GetAllActorswithTag :Tag "ExitGate"))\n        (for gate gates\n          (Transformation|SetActorLocation :self gate :NewLocation (Math|Vector|MakeVector 1200.0 3400.0 (+ 250.0 (Variables|Default|GetGateHeight))))))\n      (if (> (.y pos) 3600.0) (Variables|Default|SetEscaped true))))\n  (if (Variables|Default|GetEscaped)\n    (Variables|Default|SetObjective "COMPOUND BREACHED / You escaped.")\n    (Variables|Default|SetPrompt "[R] Play again")))\n\n')
    return {"lights":changed,"saved":call("asset.AssetTools","save_assets",asset_paths=[])}
